def first_bad(commits, is_bad):
    lo, hi = 0, len(commits) - 1  # lo good, hi bad
    calls = 0
    while hi - lo > 1:
        mid = (lo + hi) // 2
        calls += 1
        if is_bad(commits[mid]):
            hi = mid
        else:
            lo = mid
    return commits[hi], calls

def summarise(output):
    result = {'staged': [], 'unstaged': [], 'untracked': []}
    for line in output.splitlines():
        if len(line) < 4:
            continue
        x, y, path = line[0], line[1], line[3:]
        if x == '?' and y == '?':
            result['untracked'].append(path)
            continue
        if x != ' ':
            result['staged'].append(path)
        if y != ' ':
            result['unstaged'].append(path)
    return {k: sorted(v) for k, v in result.items()}
